let filmController=null;let revealActive=false,revealController=null,closeStoryPanel=null;let filmActive=false,endingSequenceActive=false,creditsRun=null,closeEvidence=null,cancelStory=null;const evidenceByCase=new Map(),storySeen=new Set(),openingFound=new Set();let lobbyPlaced=false,ambientTick=0;
function film(kind,after=()=>{},{signal}={}){if(filmActive||signal?.aborted)return Promise.resolve();filmActive=true;voice.stop();if(kind==='opening'){world?.setEnabled(false);sound.setSituation({phase:'arrival'});return playArrival({world,autoplay:true,soundEnabled:sound.enabled,onSoundChange:enabled=>{sound.enabled=enabled;$('#audio').textContent=enabled?'SOUND ON':'SOUND OFF';if(enabled)sound.start();else if(sound.ctx)sound.applyVolume();},onFinish:()=>{filmActive=false;world?.setMode(screen==='explore'?'play':'home');world?.setEnabled(screen==='explore');updateMusic();$('#solo')?.focus();after();}});}filmController?.abort();const controller=new AbortController();filmController=controller;const abort=()=>controller.abort();signal?.addEventListener('abort',abort,{once:true});return playCinematic(kind,{signal:controller.signal,muted:kind==='opening'||!sound.enabled,onStart:()=>{world?.setEnabled(false);sound.setSituation({phase:'film'});},onFinish:()=>{if(filmController!==controller)return;filmController=null;filmActive=false;world?.setEnabled(screen==='explore');updateMusic();}}).finally(()=>signal?.removeEventListener('abort',abort));}
let stories=[],state=null,room=null,world=null,screen='home',lastRender='',savedTurns=new Set(),lastCue=-1,closeAt=0,username='',quality=false,pendingChoice=null;let preferences=readPreferences();document.documentElement.dataset.subtitles=preferences.subtitles?'on':'off';
