function review(){voice.stop();const run=state.id,turn=state.turn;const entry=state.log.at(-1),sc=stories[entry.story].scenes[entry.scene],r=entry.results.find(p=>p.id===id);
 if(lastCue!==state.turn){r.good?sound.cue(true):sound.warning();world?.respond(r.good);world?.setSecurity(operationalState(state.log,id).pressure);lastCue=state.turn;}
 view(panel(`${!r.good?consequenceWarning(r,sc):'<span class="eyebrow">DECISION DEFENSIBLE</span><h2>One less problem at sunrise.</h2>'}<section class="operations-status"><strong>${esc(operationalState(state.log,id).label)}</strong><p>${esc(operationalState(state.log,id).message)}</p></section>${entry.scene===2?threadUpdate():''}<div class="feedback ${r.good?'good':''}"><span class="eyebrow">${r.good?'WHY IT WORKS':'WHY THIS WAS UNSAFE'}</span><p><strong>Your call:</strong> ${esc(r.timeout?'No answer within '+(r.limitSeconds||50)+' seconds.':answerOptions(sc,state.turn,state.route.length*3)[r.choice])}</p><p>${esc(sc.why)}</p>${r.good?'<p><strong>Effect:</strong> '+esc(sc.good)+'</p>':''}<p class="legal">${esc(sc.law)}</p></div>${r.good?'<p class="fine">+'+r.delta+' POINTS · +8 INTEGRITY (up to 100) · STREAK '+mine().streak+'</p>':''}${room?leaderboard(false):''}${!r.good&&!room?'<p class="crew-radio-reaction" role="status"></p><button id="acknowledge" class="warning-ack">I UNDERSTAND THE CONSEQUENCE</button><p class="fine">Acknowledge the warning to continue. Your penalty remains.</p>':''}<div class="row">${button('continue',room?'READY FOR NEXT QUESTION →':state.turn===state.route.length*3-1?'FINISH SHIFT →':'FOLLOW THE LEAD →',true)}${!room?button('explore','RETURN TO FLOOR'):''}</div>${room?'<p class="fine" id="review-clock">Next question in 8s. All ready moves on immediately.</p>':''}`,'case-panel'),'review');
 if(!r.good){document.body.classList.add('unsafe-review');if(!room){$('#continue').disabled=$('#explore').disabled=true;if(!r.good)voice.play('warning',{priority:true,onComplete:()=>{if(state?.id===run&&state.turn===turn&&state.phase==='review')playWrongCallReaction();}});bind('#acknowledge',()=>{playWrongCallReaction();$('#continue').disabled=$('#explore').disabled=false;$('#acknowledge').disabled=true;$('#acknowledge').textContent='WARNING ACKNOWLEDGED';$('#continue').focus();});}}
 bind('#continue',()=>{if(room)room.action('ready',{run:state.id,turn:state.turn});else{advance(state,id);publish();if(state.phase==='explore')interact('case');}});bind('#explore',()=>{advance(state,id);publish();});
}
function riskReminder(){const risk=riskFor(state.log,id,mine().integrity);return risk.consecutive||mine().integrity<=30?`<div class="risk-reminder" role="status">⚠ ${mine().integrity<=30?'CRITICAL INTEGRITY':risk.consecutive+' UNSAFE CALL'+(risk.consecutive===1?'':'S')+' IN A ROW'} · ${mine().integrity}/100 integrity. A wrong answer costs 40 points, 14 integrity and your streak. Check the evidence before you lock in.</div>`:'';}
function missionBreak(){saveCaseCheckpoint();view(panel(`<span class="eyebrow">SOLO INTERMISSION / CASE FILE SEALED</span><h2>The same job. Another source.</h2>${threadUpdate()}${consequenceHtml()}<p>One story closed. ${mine().integrity>=70?'You’ve kept the incident under control.':'The city is feeling the effects of those shortcuts.'} Take a breath before the next call.</p><div class="feedback good"><span class="eyebrow">NEXT LEAD / ${esc(currentStory().sector)}</span><h3>${esc(currentStory().title)}</h3><p>${esc(currentStory().brief)}</p><p><strong>Destination: floor ${floorForCase(state.route[Math.floor(state.turn/3)])} · ${esc(floorInfo(floorForCase(state.route[Math.floor(state.turn/3)])).name)}</strong></p><p>${esc(decisionNotice(state.turn,state.route.length*3,state.timed))}</p></div><p class="fine">Use Lift / Floors to travel, then follow the yellow arrow. Field Tools → Navigate to case is a direct shortcut. No timer during solo mission breaks. Stretch, get water, or explore the floor.</p><div class="row">${button('resume','TAKE THE NEXT CASE →',true)}${button('walk','COFFEE & FLOOR WALK')}</div>`),'break');bind('#resume',()=>{advance(state,id);publish();interact('case');});bind('#walk',()=>{advance(state,id);publish();});}
function leaderboard(final){const players=[...state.players].sort((a,b)=>b.points-a.points||b.integrity-a.integrity||b.correct-a.correct);return `<h3>${final?'Shift leaderboard':'Live standings'}</h3><table><thead><tr><th>RANK</th><th>ANALYST</th><th>POINTS</th><th>INTEGRITY</th><th>STREAK</th></tr></thead><tbody>${players.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.alias)}${p.id===id?' · YOU':''}</td><td>${p.points}</td><td>${p.integrity}/100</td><td>${final?p.best:p.streak}${final?' best':''}</td></tr>`).join('')}</tbody></table>`;}
function debrief(){return state.log.map(e=>{const sc=stories[e.story].scenes[e.scene],r=e.results.find(x=>x.id===id);return `<details><summary>${r.good?'✓':'✕'} ${e.turn+1}. ${esc(stories[e.story].title)} · ${esc(sc.tag)} ${r.timeout?' / TIMEOUT':''}</summary><p><strong>Your call:</strong> ${esc(r.timeout?'No response before the deadline.':answerOptions(sc,e.turn,state.route.length*3)[r.choice])}</p><p><strong>Best response:</strong> ${esc(sc.a)}</p><p><strong>${r.good?'Why it worked':'What went wrong'}:</strong> ${esc(sc.why)}</p><p><strong>Effect:</strong> ${esc(r.good?sc.good:sc.effect)}</p><p class="legal">${esc(sc.law)}</p></details>`;}).join('');}
async function endingSequence(runId,kind){
 if(!state||filmActive||endingSequenceActive)return;
 voice.stop();revealController?.abort();
 const controller=new AbortController();revealController=controller;endingSequenceActive=true;const releaseMedia=preloadCinematics([kind,'credits'],{signal:controller.signal});
 const isCurrent=()=>!controller.signal.aborted&&state?.id===runId&&state.phase==='end';
 try{
  await playEndingSequence({signal:controller.signal,isCurrent,
   ending:()=>film(kind,()=>{},{signal:controller.signal}),
   credits:()=>film('credits',()=>{},{signal:controller.signal})
  });
 }finally{releaseMedia();if(revealController===controller){revealController=null;revealActive=false;filmActive=false;endingSequenceActive=false;updateMusic();}}
}
function ending(){if(!state.finalDeduction){showFinalDeduction();return;}try{localStorage.removeItem(CHECKPOINT_KEY);}catch{}const p=mine(),outcome=endingFor(p.correct,state.log.length),accuracy=Math.floor(p.correct/state.log.length*100);closeAt=room?(state.endsAt||Date.now()+300000):0;view(panel(`<span class="eyebrow">06:00 AM / SHIFT COMPLETE</span><h2>${outcome==='good-ending'?'You held the line. The city wakes safer.':'Trust went dark. The night is not over.'}</h2><p class="ending-verdict ${outcome}">${accuracy}% CORRECT · ${outcome==='good-ending'?'HEROIC ENDING — 80% TARGET MET':'DARK ENDING — BELOW 80%'}</p><p>${p.correct===state.log.length?'Every decision held up. The shortcuts didn’t get a vote.':`${state.log.length-p.correct} decision${state.log.length-p.correct===1?' needs':'s need'} a closer look. Open the incident reviews below to see the choice, the legal reason and the effect.`}</p><div class="scorehero"><div><b>${p.points}</b><span>POINTS</span></div><div><b>${p.correct}/${state.log.length}</b><span>DEFENSIBLE CALLS</span></div><div><b>${p.integrity}</b><span>INTEGRITY</span></div></div><span class="eyebrow">LEVEL / ${esc(levelFor(p.points))}</span>${room?leaderboard(true):''}<section class="thread-resolution"><span class="eyebrow">BLUE LANTERN / CASE RESOLUTION</span><h3>${esc(revealFor(state.log,id,state.route.length).title)}</h3>${revealFor(state.log,id,state.route.length).beats.map(text=>'<p>'+esc(text)+'</p>').join('')}</section><p class="soundtrack-credit">Soundtrack By <strong>Renjith Mohan M R</strong></p>${deductionReport()}${dpoHandover()}<h3>Your incident review</h3>${debrief()}${room?'<p class="fine" id="erase-clock">Usernames are held only in this session. Closing the leaderboard clears this session. It closes automatically after five minutes.</p>':'<p class="fine">Your completed cases and solo score are saved in this browser. No username is stored.</p>'}<div class="row">${button('finish',room?'CLOSE LEADERBOARD & CLEAR USERNAME':'CLOCK OUT →',true)}${button('replay-ending','REPLAY YOUR ENDING')}${button('replay-credits','REPLAY CREDITS')}</div>${legalNote()}`,'wide'),'end');bind('#download-handover',downloadHandover);bind('#finish',()=>room?exitRoom():home());bind('#replay-credits',()=>film('credits'));bind('#replay-ending',()=>endingSequence(state.id,outcome));if(creditsRun!==state.id){creditsRun=state.id;endingSequence(state.id,outcome);}}
async function exitRoom(message){filmController?.abort();revealController?.abort();const r=room;room=null;state=null;username='';pendingChoice=null;closeAt=0;home();if(r)await r.close().catch(()=>{});if(message&&!room)notify(message);}
function archive(){view(panel(`<span class="eyebrow">CASE ARCHIVE / ONE CONNECTED NIGHT</span><h2>Every shortcut leaves a trail.</h2><div class="archive">${stories.map((s,i)=>`<article><small>${String(i+1).padStart(2,'0')} / ${esc(s.sector)} · ${seen.includes(s.id)?'COMPLETED':'UNEXPLORED'}</small><h3>${esc(s.title)}</h3><p>${esc(s.brief)}</p></article>`).join('')}</div><div class="row">${button('back','BACK TO OPERATIONS',true)}</div>`,'wide'),'archive');bind('#back',home);}
function history(){view(panel(`<span class="eyebrow">THIS BROWSER ONLY / SOLO HISTORY</span><h2>Your morning handovers.</h2>${records.length?`<table><thead><tr><th>DATE</th><th>POINTS</th><th>CORRECT</th><th>INTEGRITY</th></tr></thead><tbody>${records.slice(-10).reverse().map(r=>`<tr><td>${esc(new Date(r.at).toLocaleDateString())}</td><td>${r.points}</td><td>${r.correct}/${r.total}</td><td>${r.integrity}</td></tr>`).join('')}</tbody></table>`:'<p>No completed solo shifts yet. The city is waiting.</p>'}<p class="fine">${seen.length}/10 completed cases remembered. Online usernames and leaderboards are never saved here.</p><div class="row">${button('back','BACK',true)}${button('clear','RESET COMPLETED-CASE HISTORY')}</div>`));bind('#back',home);bind('#clear',()=>{seen=[];store();history();notify('Completed-case history reset. Solo scores retained.');});}
