bind('#chikku-find',showChikkuFind);bind('#field-operations',()=>{if(state?.phase==='explore'&&screen==='explore'&&!filmActive){if(world?.status().near)showFieldOperations();else notify('Follow the yellow marker to your active table to use its operations terminal.');}});bind('#case-journal',showJournal);bind('#recover-lift',()=>{if(!state||state.phase!=='explore'||filmActive||document.querySelector('dialog[open]'))return;voice.stop();world?.returnToLift();notify('Back at the lift on floor '+world?.status().floor+'. Your evidence and score are unchanged.');});bind('#arrival-leads',showOpeningBoard);bind('#case-thread',showCaseThread);bind('#ask-colleague',showCrew);bind('#floor-directory',showFloorDirectory);bind('#accessibility',showAccessibility);bind('#flashlight',()=>world?.toggleTorch());bind('#evidence',openEvidence);bind('#exit',()=>{if(room)exitRoom();else home();});bind('#audio',()=>{const enabled=sound.toggle();if(!enabled)voice.stop();$('#audio').textContent=enabled?'SOUND ON':'SOUND OFF';if(enabled)sound.start();});bind('#quality',()=>{quality=!quality;world?.setQuality(quality);$('#quality').textContent=quality?'LOW FX':'HIGH FX';});bind('#help',guide);bind('#inspect',()=>world?world.interact():interact('case'));bind('#scan',()=>{if(state&&operationalState(state.log,id).restricted)interact('map');else world?.scan();});bind('#guide',()=>{if(!room&&state?.turn===0&&!openingComplete(openingFound)){world?.guide();showOpeningBoard();return;}world?.guide();notify('At the active terminal. Inspect to open the case.');});bind('#quit',()=>{if(room)exitRoom();else home();});
