function inspectOpening(index){if(!Number.isInteger(index)||index<0||index>2)return;showOpeningBoard(index);}
function showOpeningBoard(initial=null){
 if(document.querySelector('dialog[open]'))return;
 let selected=Number.isInteger(initial)&&initial>=0&&initial<3?initial:null,closed=false;
 const dialog=document.createElement('dialog');dialog.className='office-card';dialog.setAttribute('aria-label','Arrival evidence board');
 function collect(){if(selected===null)return;if(!openingFound.has(selected)){openingFound.add(selected);sound.discovery();sound.spatial('paper');voice.play(selected===2?'mira':'evidence');}if(state?.phase==='explore')lastRender='';}
 function back(){selected=null;draw();dialog.querySelector('[data-lead]')?.focus();}
 function draw(){
  const head='<section class="arrival-brief"><span class="eyebrow">MIDNIGHT ENTRY / FIELD NOTES</span>';
  if(selected!==null){const c=OPENING_LEADS[selected];dialog.innerHTML=head+'<h2>'+esc(c.title)+'</h2><p>'+esc(c.body)+'</p><p>'+esc(c.question)+'</p><p class="fine">'+openingFound.size+'/3 collected · No question clock is running.</p><button class="primary lead-back">← BACK TO ALL EVIDENCE</button></section>';dialog.querySelector('.lead-back').onclick=back;}
  else{dialog.innerHTML=head+'<h2>Three leads. One contradiction.</h2><p>Inspect or reread any of the three clues.</p>'+OPENING_LEADS.map((c,i)=>'<button class="secondary" data-lead="'+i+'">'+(openingFound.has(i)?'✓ REVIEW · ':'INSPECT · ')+esc(c.title)+'</button>').join('')+'<p class="fine">'+openingFound.size+'/3 collected. '+(openingComplete(openingFound)?'Arrival clues complete. Next: follow the yellow arrow to your active case desk on floor '+floorForCase(state.route[0])+'. Inspect its three case records, then open its terminal. Field Tools → Navigate to case takes you straight there.':'No question clock is running.')+'</p><button class="primary lead-close">'+(openingComplete(openingFound)?'CONTINUE TO CASE →':'RETURN TO GAME →')+'</button></section>';dialog.querySelectorAll('[data-lead]').forEach(button=>button.onclick=()=>{selected=Number(button.dataset.lead);collect();draw();dialog.querySelector('.lead-back').focus();});dialog.querySelector('.lead-close').onclick=close;}
 }
 function close(){if(closed)return;closed=true;dialog.close();dialog.remove();if(state&&openingComplete(openingFound)){showArrivalRoute();return;}if(state&&lastRender==='')render();else world?.setEnabled(screen==='explore'&&!filmActive);}
 collect();draw();world?.setEnabled(false);document.body.append(dialog);dialog.showModal();dialog.querySelector('button')?.focus();dialog.addEventListener('cancel',e=>{e.preventDefault();if(selected!==null)back();else close();});
}

