function showStoryPanel(label,title,body){const panel=storyDialog(title,'<span class="eyebrow">'+esc(label)+'</span><h2>'+esc(title)+'</h2><p>'+esc(body)+'</p><button class="primary story-close">RETURN TO OFFICE</button>');if(panel)panel.dialog.querySelector('.story-close').onclick=panel.close;}
function showConversation(index){if(!state||state.phase!=='explore'||filmActive)return;voice.stop();const progress=threadProgress(state.log,state.route.length),conversation=clueConversation(index,currentStory().id,caseClues(),progress,operationalState(state.log,id).pressure);if(caseClues().size){const source=dossiers[currentStory().id].clues[[...caseClues()].at(-1)];conversation.topics[1].reply+=' Source on the board: '+source[0]+' — '+source[1];}const reaction=crewReaction(stories,state.log,id,index);const panel=storyDialog(conversation.name,'<span class="eyebrow">FIELD CONVERSATION / BLUE LANTERN</span><h2>'+esc(conversation.name)+'</h2><aside class="crew-reaction" data-mood="'+reaction.mood+'"><strong>'+esc(reaction.title)+'</strong><p>'+esc(reaction.line)+'</p></aside><div class="dialogue-topics"></div><div class="dialogue-response" aria-live="polite">Choose a question. Follow-ups unlock as you inspect records and complete cases.</div><p class="fine">'+(room?'Shared multiplayer clocks continue while talking.':'No question clock runs during floor exploration.')+'</p><button class="primary story-close">RETURN TO OFFICE</button>');if(!panel)return;const {dialog,close}=panel;const list=dialog.querySelector('.dialogue-topics');list.innerHTML=conversation.topics.map((t,i)=>'<button class="secondary" data-topic="'+i+'" '+(t.available?'':'disabled')+'>'+esc(t.label)+(t.available?'':'<small>'+esc(t.requires)+'</small>')+'</button>').join('');list.querySelectorAll('[data-topic]').forEach(button=>button.onclick=()=>{const topic=conversation.topics[Number(button.dataset.topic)];if(topic.available){voice.stop();dialog.querySelector('.dialogue-response').innerHTML='<p><strong>Simon Ghost Riley</strong><br>'+esc(topic.label)+'</p><p><strong>'+esc(conversation.name)+'</strong><br>'+esc(topic.reply)+'</p>';}});dialog.querySelector('.story-close').onclick=close;}
function showCaseThread(){if(!state||filmActive)return;const progress=threadProgress(state.log,state.route.length),current=caseLink(currentStory().id);const content='<span class="eyebrow">DPO JOURNAL · NEXT LEAD ON FLOOR '+floorForCase(state.route[Math.min(Math.floor(state.turn/3),state.route.length-1)])+'</span><p>Preserve evidence, distinguish facts from assumptions, coordinate containment and document your reasoning.</p><span class="eyebrow">ONE NIGHT / '+progress.count+' OF '+progress.total+' CASES LINKED</span><h2>'+esc(THREAD_TITLE)+'</h2><p>A badge suggests an intruder. A shared service account identifies a system. Find the signed authorisation before naming a person.</p><h3>Current case connection</h3><p>'+esc(current.body)+'</p>'+progress.entries.map(e=>'<article class="thread-link"><span class="eyebrow">CASE LINK '+e.caseIndex+'</span><h3>'+esc(e.title)+'</h3><p>'+esc(e.body)+'</p></article>').join('')+(!progress.complete?'<p class="fine">More findings unlock when you complete cases. Findings are preserved even after unsafe calls; your decisions determine containment.</p>':'<p class="fine">The authorisation trail is complete. Your calls determine what survives until dawn.</p>')+'<button class="primary story-close">RETURN TO OFFICE</button>';const panel=storyDialog(THREAD_TITLE,content);if(panel)panel.dialog.querySelector('.story-close').onclick=panel.close;}

function showCrew(){if(!state||filmActive)return;const panel=storyDialog('Speak to the night crew','<span class="eyebrow">BLUE LANTERN / NIGHT CREW</span><h2>Who do you want to question?</h2>'+COLLEAGUES.map((person,i)=>'<button class="secondary crew-question" data-person="'+i+'">'+esc(person.name)+'</button>').join('')+'<button class="primary story-close">RETURN TO OFFICE</button>');if(!panel)return;panel.dialog.querySelectorAll('[data-person]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.person);panel.close();interact({type:'colleague',index});});panel.dialog.querySelector('.story-close').onclick=panel.close;}

