function showFloorDirectory(){if(!state||state.phase!=='explore'||filmActive)return;voice.play('lift');sound.spatial('lift');const current=world?.status().floor||47,target=floorForCase(state.route[Math.floor(state.turn/3)]);const p=storyDialog('Lift directory','<span class="eyebrow">MERIDIAN DATAWORKS / BUILDING DIRECTORY</span><h2>Lift destination</h2><p>For the in-world lift, walk into the cabin behind the office entrance. Look at the illuminated floor panel and press E on a number. These controls also let you enter the cabin directly.</p><p>Currently on floor '+current+'. Active case: floor '+target+'.</p><div class="floor-list">'+FLOORS.map(f=>'<button class="secondary '+(f.number===current?'current-floor ':'')+(f.number===target?'target-floor':'')+'" data-floor="'+f.number+'"><strong>'+f.number+' / '+f.name+(f.number===target?' · ACTIVE CASE':'')+'</strong><small>'+f.description+'</small></button>').join('')+'</div><button class="primary story-close">RETURN TO FLOOR</button>');if(!p)return;p.dialog.querySelector('.story-close').onclick=p.close;p.dialog.querySelectorAll('[data-floor]').forEach(button=>button.onclick=async()=>{const floor=Number(button.dataset.floor);p.dialog.querySelectorAll('button').forEach(b=>b.disabled=true);const run=state.id;p.close();const arrived=await world?.takeLift(floor);if(!state||state.id!==run)return;lastRender='';render();notify(arrived?'Floor '+floor+' · '+floorInfo(floor).name:'You are already on floor '+floor+'.');});}
function showAccessibility(){const p=storyDialog('Accessibility','<span class="eyebrow">ACCESSIBILITY / DISPLAY</span><h2>Field preferences</h2><button class="secondary" id="toggle-banter">PLAYFUL BANTER: '+(preferences.banter?'ON':'OFF')+'</button><button class="secondary" id="toggle-subtitles">DIALOGUE SUBTITLES: '+(preferences.subtitles?'ON':'OFF')+'</button><button class="secondary" id="toggle-outline">HIGH-CONTRAST OUTLINE: '+(preferences.outline?'ON':'OFF')+'</button><p>Outlines identify the object under your reticle. This setting does not affect decisions or timers.</p><button class="primary story-close">DONE</button>');if(!p)return;p.dialog.querySelector('.story-close').onclick=p.close;p.dialog.querySelector('#toggle-banter').onclick=e=>{preferences.banter=!preferences.banter;if(!preferences.banter)voice.stopBanter();savePreferences(preferences);e.target.textContent='PLAYFUL BANTER: '+(preferences.banter?'ON':'OFF');};p.dialog.querySelector('#toggle-subtitles').onclick=e=>{preferences.subtitles=!preferences.subtitles;document.documentElement.dataset.subtitles=preferences.subtitles?'on':'off';if(!preferences.subtitles)showSpeechCaption(null);savePreferences(preferences);e.target.textContent='DIALOGUE SUBTITLES: '+(preferences.subtitles?'ON':'OFF');};p.dialog.querySelector('#toggle-outline').onclick=e=>{preferences.outline=!preferences.outline;world?.setOutline(preferences.outline);savePreferences(preferences);e.target.textContent='HIGH-CONTRAST OUTLINE: '+(preferences.outline?'ON':'OFF');};}
async function waitForAssets(){if(!world)return;const el=document.createElement('section');el.className='asset-loader';el.setAttribute('aria-label','Loading the investigation');el.innerHTML='<span class="eyebrow">GHOST SHIFT / NIGHT-SHIFT ROASTS</span><h2>Your confidence arrived first.</h2><progress max="100" value="0" aria-label="Loading progress"></progress><p class="loading-count" role="status">0%</p><p class="fine">Three records. Four options. Somehow you will blame the mouse.</p><aside class="loading-trivia"><span>UNSOLICITED NIGHT-SHIFT COMMENTARY</span><p class="loading-fact"></p></aside>';document.body.append(el);const stopFacts=rotateLoadingFacts(el.querySelector('.loading-fact'));const stop=world.loading.subscribe(s=>{el.querySelector('progress').value=s.percent;el.querySelector('.loading-count').textContent=s.percent+'%';});try{await world.ready;const failed=world.loading.snapshot().failed;if(failed.length)notify('Some assets could not load. Available investigation controls remain ready.');}catch{notify('Graphics preparation could not finish. Use Low FX if needed.');}finally{stop();stopFacts();el.remove();}}

